/bin/bash -c "python - <<'PY'
from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB'))
# Rows and runs for colors with tighter conditions
for y in range(0,90,2):
 r,g,b=im[y,:,0],im[y,:,1],im[y,:,2]
 masks={
  'B':(b>90)&(g>45)&(b>r*1.5)&(b>g*1.05),
  'Y':(r>100)&(g>80)&(b<80)&(r>g*.9),
  'O':(r>110)&(g>25)&(g<135)&(b<75)&(r>g*1.5),
  'K':(r<55)&(g<55)&(b<60),
 }
 parts=[]
 for k,m in masks.items():
  idx=np.where(m)[0]
  runs=[]
  if len(idx):
   st=pr=idx[0]
   for x in idx[1:]:
    if x>pr+1:
     if pr-st>=1:runs.append((st,pr))
     st=x
    pr=x
   if pr-st>=1:runs.append((st,pr))
  parts.append(k+':'+','.join(f'{a}-{b}' for a,b in runs if b>135 or a>135))
 print(f'{y:02d}', ' '.join(parts))
PY"

